BEGIN;
INSERT INTO brief_template_bundle (version, skeleton, tactic_overrides, presets, label)
VALUES (
  1,
  $brief_skeleton_json${"version": 1, "sections": [{"id": "admin", "title": "Project admin", "fields": [{"id": "client_brand", "label": "Client / brand", "helper": "Company and brand names.", "placeholder": "[Client] & [Brand]", "rows": 2}, {"id": "project_name", "label": "Project name", "helper": "Working title for this deliverable.", "placeholder": "", "rows": 2}, {"id": "job_number", "label": "Job / WBS number", "helper": "Internal tracking number if applicable.", "placeholder": "", "rows": 1}, {"id": "date_today", "label": "Brief date", "helper": "", "placeholder": "", "rows": 1}, {"id": "creative_handover_date", "label": "Creative handover date", "helper": "Target date creative leaves agency.", "placeholder": "", "rows": 1}, {"id": "in_market_date", "label": "In-market / live date", "helper": "", "placeholder": "", "rows": 1}, {"id": "agency_leads", "label": "Agency project leads", "helper": "Account, PM, creative leads.", "placeholder": "", "rows": 3}, {"id": "other_agencies_vendors", "label": "Other agencies / vendors", "helper": "Media, deployment, tech partners and roles.", "placeholder": "", "rows": 3}]}, {"id": "strategy", "title": "Strategy", "fields": [{"id": "marketing_objectives", "label": "Marketing / promotional objectives", "helper": "What business outcomes this work supports.", "placeholder": "", "rows": 4}, {"id": "barrier_opportunity", "label": "Key barrier / opportunity", "helper": "Insight framing the ask.", "placeholder": "", "rows": 3}, {"id": "si_kpi", "label": "SI / KPI / success metrics", "helper": "Brand imperatives or measurable KPIs.", "placeholder": "", "rows": 3}, {"id": "tactic_objectives", "label": "Tactic objectives", "helper": "What this specific unit must accomplish.", "placeholder": "", "rows": 3}]}, {"id": "audience", "title": "Audience", "fields": [{"id": "primary_audience", "label": "Primary audience / segment", "helper": "Who we are reaching.", "placeholder": "", "rows": 2}, {"id": "desired_behavior", "label": "Desired behavior change", "helper": "What we want them to think or do differently.", "placeholder": "", "rows": 3}, {"id": "segments_specialties", "label": "Segments / specialties / targeting notes", "helper": "Checkbox-style segments, CRM universes, specialties.", "placeholder": "", "rows": 4}]}, {"id": "context", "title": "Context", "fields": [{"id": "background", "label": "Background", "helper": "Why now; prior assets; strategic context.", "placeholder": "", "rows": 5}]}, {"id": "execution", "title": "Execution", "fields": [{"id": "deliverables", "label": "Tactical execution / deliverables", "helper": "Exactly what we are creating (formats, versions, counts).", "placeholder": "", "rows": 6}, {"id": "specs_reference", "label": "Specs / reference links", "helper": "Platform specs, legal refs, source asset IDs.", "placeholder": "", "rows": 4}]}, {"id": "creative", "title": "Creative & messaging", "fields": [{"id": "key_messages", "label": "Key messages & data", "helper": "Core / secondary messages; data to include or avoid.", "placeholder": "", "rows": 5}, {"id": "story_flow", "label": "Story flow / narrative", "helper": "Sequence, beats, or email sections.", "placeholder": "", "rows": 4}, {"id": "copy_requirements", "label": "Copy requirements / best practices", "helper": "Subject lines, headlines, character limits, disclosure placement.", "placeholder": "", "rows": 5}, {"id": "art_pd_xd", "label": "Art / PD / XD requirements", "helper": "Layouts, mockups, templates, design mandatories.", "placeholder": "", "rows": 5}, {"id": "tech_dev_deployment", "label": "Tech / dev / deployment", "helper": "Build method (HTML, ET code), hosting, UTMs, trafficking handoffs.", "placeholder": "", "rows": 5}]}, {"id": "compliance", "title": "Compliance & submission", "fields": [{"id": "mandatories", "label": "Mandatories", "helper": "ISI, PI, logos, legal footer, branding rules.", "placeholder": "", "rows": 5}, {"id": "submission_files", "label": "Submission files expected", "helper": "PRB/RC packages, mockups, annotations.", "placeholder": "", "rows": 4}]}, {"id": "process", "title": "Process", "fields": [{"id": "reviews", "label": "Reviews", "helper": "Client rounds, PRB/RC/JRC, broadcast reviews.", "placeholder": "", "rows": 4}, {"id": "assumptions", "label": "Assumptions", "helper": "", "placeholder": "", "rows": 4}, {"id": "exclusions", "label": "Exclusions", "helper": "Explicitly out of scope.", "placeholder": "", "rows": 3}]}, {"id": "operations", "title": "Operations", "fields": [{"id": "estimate_timeline", "label": "Estimate / fee / OOP", "helper": "Budget notes if known.", "placeholder": "", "rows": 2}, {"id": "timeline_milestones", "label": "Timeline milestones", "helper": "Key dates (CR, PRB, AFD, go-live).", "placeholder": "", "rows": 4}]}, {"id": "internal_production", "title": "Internal production (decks / MLR)", "fields": [{"id": "asset_checklist", "label": "Asset checklist", "helper": "Print, PDF, deck, email, Launchpad, etc.", "placeholder": "", "rows": 3}, {"id": "creative_asset_needs", "label": "Creative asset needs questionnaire", "helper": "Veeva code on piece, ISI, PI insert, internal vs external.", "placeholder": "", "rows": 4}, {"id": "development_submission_needs", "label": "Development & submission needs", "helper": "Mechanical vs PDF, annotations, marketing notes, related materials.", "placeholder": "", "rows": 4}, {"id": "scope_roles_deliverables", "label": "Scope — roles & detailed deliverables", "helper": "Producer, copy, art, edit, submissions, presentation services.", "placeholder": "", "rows": 8}, {"id": "client_approvals_rounds", "label": "Client approvals & review rounds", "helper": "Sr client approval, JRC rounds, target in-market.", "placeholder": "", "rows": 4}]}, {"id": "close", "title": "Close", "fields": [{"id": "approvals_signoff", "label": "Brief approvals", "helper": "Agency + client sign-off lines.", "placeholder": "", "rows": 2}, {"id": "appendix", "label": "Appendix / metadata", "helper": "UTM grid, content pillar, campaign naming, team checklist.", "placeholder": "", "rows": 4}]}]}$brief_skeleton_json$::jsonb,
  $brief_overrides_json${"version": 1, "overrides": {"hcp_email": {"fieldHints": {"copy_requirements": "Rep-triggered or permissions email: Veeva / ET template, salutations, rep customizable blocks, footer/legal.", "tech_dev_deployment": "Typical: ESP build, test sends, UTM matrix to deployment partner."}}, "crm_email": {"fieldHints": {"tech_dev_deployment": "Calendar/trigger programs: note ESP (e.g. SFMC), partner building sends, BRD/FRD handoff.", "deliverables": "State initial vs triggered send and versioning vs existing approved creative."}}, "paid_social_feed": {"fieldHints": {"specs_reference": "Placement (in-feed, stories), ratios, max copy lengths, CTA options.", "submission_files": "Mockups for desktop/mobile; storyboards where applicable."}}, "paid_social_video": {"fieldHints": {"specs_reference": "Video duration, aspect ratios (e.g. 1:1, 4:5, 9:16), sound on/off, file format (MP4), hook timing.", "tech_dev_deployment": "Broadcast resize/repurpose notes; media agency trafficking handoff."}}, "organic_social": {"fieldHints": {"deliverables": "Clarify organic posting vs ads-only page; profile/cover specs; engagement settings.", "mandatories": "Pharma page templates, HCP-only labeling on cover, disclaimer language."}}, "slide_deck_scientific": {"fieldHints": {"scope_roles_deliverables": "Training or MLR decks: slide-by-slide objectives, disclaimers, end matter; roles across copy/art/submissions.", "submission_files": "PPT + PDF; speaker notes; internal-only labeling."}}, "brand_site": {"fieldHints": {"tech_dev_deployment": "CMS, hosting, analytics, redirect/URL strategy.", "deliverables": "Wireframes, responsive breakpoints, component library ties."}}}}$brief_overrides_json$::jsonb,
  $brief_presets_json${"version": 1, "presets": [{"id": "internal_ml_training_deck", "label": "Internal MLR training deck", "tactic_keys": ["slide_deck_scientific"], "field_defaults": {"marketing_objectives": "Develop a training deck that familiarizes the field with approved core materials and how to use them with HCPs.", "tactic_objectives": "Educate the sales force on leveraging in-market materials at launch; include annotations where reps should focus discussion.", "deliverables": "Training deck covering each core material slide-by-slide: objective of each page, details for HCP dialogue, known objection handling.\nOutputs: presentation file and PDF for review; speaker notes as needed.", "key_messages": "Align to brand strategy and PI-based claims only; note any N/A sections pending MLR.", "art_pd_xd": "Leverage existing annotated training deck template where applicable; maintain brand design system.\nEach slide: Internal Only / Confidential disclaimer.\nInclude end matter / thank-you slide.", "mandatories": "Same design mandatories as reference template; internal-only labeling; final thank-you slide with disclaimer.", "submission_files": "Files prepared per client submission guidelines; annotations per AMA where applicable for RC.", "reviews": "Multiple client reviews for message and layout; RC reviews (initial layout + final proof).", "asset_checklist": "Deck with speaker notes; PDF; internal distribution.\nBranded / non-OPDP release per routing.", "creative_asset_needs": "Confirm: Veeva code on piece; ISI requirements; PI insert; internal-only flag.", "development_submission_needs": "PDF vs mechanical timing; comp requirements; hosting (e.g. Veeva Exchange); submission type (New/Successor); annotations/fact-check; marketing notes.", "scope_roles_deliverables": "Integrated producer: timeline, approvals, RC packages.\nCopy: brief-led copy, annotations for RC, RC meetings.\nArt: direction to presentation services.\nEdit: fact-check, reference updates, layout reads.\nSubmissions: Veeva upload, queries, vault/Promomats.\nPresentation services: deck design per AD, PPT + PDF, brand compliance.", "client_approvals_rounds": "Estimate client review rounds before final JRC; client review-day allocation; JRC rounds forecast; target in-market window; rate card / SOW treatment.", "appendix": "Link to workflow timeline (e.g. Workfront) when available."}}, {"id": "linkedin_infeed_video_repurpose", "label": "LinkedIn in-feed video (repurpose)", "tactic_keys": ["paid_social_video"], "field_defaults": {"marketing_objectives": "Increase HCP understanding of mechanism / clinical narrative; drive clicks to deeper clinical or MOA content.", "barrier_opportunity": "Opportunity: reach HCPs in professional feed with concise video; barrier: prior asset built for another placement — resize/repurpose for LinkedIn.", "tactic_objectives": "Deliver LinkedIn in-feed video unit adapted from approved reference creative; include variable copy/CTA options where needed.", "deliverables": "LinkedIn MOA (or campaign) video aligned to reference job code.\nMultiple post copy and CTA options for submission flexibility.\nStoryboard frames + mocked post (desktop/mobile).", "specs_reference": "LinkedIn in-feed video (common guidance): MP4; AAC/MPEG4 audio; ~30 fps; destination URL with http(s); headline ~70 chars visible; intro text ~150 chars (verify current LinkedIn specs).\nAspect ratios to consider: 1:1 (square), 4:5 vertical, 16:9 landscape — confirm media plan.\nDuration often short-form for feed (e.g. ~15–30s creative target; platform allows wider range).", "copy_requirements": "Reserve first-line legal/post copy as required by brand (e.g. PI link).\nProvide headline + description variants so copy can refresh without full resubmit where policy allows.\nEnsure continuity from ad → landing experience.", "art_pd_xd": "Resize/rebuild animation from source creative; maintain ISI treatment per social guidance.\nXD: LinkedIn post mockups with storyboard for desktop/mobile.\nFull LOI/ISI presentation during full-screen states as required.", "tech_dev_deployment": "Broadcast produces/resizes video per approved storyboard.\nHand MP4 to media agency for trafficking; UTMs per tracking sheet.", "reviews": "Client reviews on storyboard/mockups; PRB rounds with mockup then video attachment as applicable.", "timeline_milestones": "Typical: CR rounds → PRB submissions → final approval → trafficking.", "appendix": "UTM / naming: pillar, campaign, source LinkedIn, sub-source in-feed sponsored post, indication, branded/unbranded."}}, {"id": "hq_crm_email_update", "label": "HQ / CRM email update", "tactic_keys": ["crm_email"], "field_defaults": {"marketing_objectives": "Educate HCPs on evolved clinical story; encourage deeper engagement with approved destination content.", "tactic_objectives": "Update branded HQ email used in calendar/trigger CRM programs; align narrative with cross-channel messaging.", "deliverables": "Updated HTML email layout; desktop + mobile proof.\nSubject lines + preheaders.\nOptional: alignment with trigger program versioning.", "story_flow": "Salutation → concise body (often comparable length to legacy) → primary CTA → secondary if any → legal/footer.", "copy_requirements": "Subject lines + preheaders; full indication ISI; state pricing/transparency footer lines where required.\nKeep promotional audience statement and unsubscribe/privacy links.", "art_pd_xd": "Refresh hero/key visual from latest approved storyboard; HQ-specific template; CTA buttons not full-bleed — preserve side whitespace.", "tech_dev_deployment": "UTMs on site CTAs for deployment partner tracking.\nBuild in ESP; test sends prior to final deployment partner send.\nBRD/FRD to partner once business rules locked.", "submission_files": "Subject/preheader; desktop/mobile captures; high-res exports.", "reviews": "Multiple client reviews; PRB submissions with revisions; final approval and test sends via partner.", "appendix": "UTM grid (Excel); align naming with email deployment taxonomy."}}, {"id": "vee_va_rep_triggered", "label": "Veeva rep-triggered email (VAE)", "tactic_keys": ["hcp_email"], "field_defaults": {"marketing_objectives": "Support appropriate HCP engagement following field interactions; drive to approved destination experiences.", "tactic_objectives": "Single branded Veeva Approved Email template with rep-customizable fields per FDM limits.", "deliverables": "(1) Layout proof desktop/mobile.\n(2) HTML Email Template (ET code) with assets zipped per platform guidance.", "copy_requirements": "Pick lists: salutations; recipient name tokens; customizable intro/closing (character limits per policy).\nSubject line options (e.g. 3–4); avoid restricted combinations if policy applies.\nPrimary CTA + supporting body per narrative.", "art_pd_xd": "Match approved header style reference; light imagery so loads reliably in email.\nRep-section placeholders clearly delineated from fixed MLR blocks.", "tech_dev_deployment": "UTMs on web CTAs; HTML QA; assets + spacer gif to ET metadata folder structure; RegOps/account creates ET code; QC test blasts multi-device.", "submission_files": "Mockups align to routed HTML; subject suggestions documented.", "reviews": "Client layout reviews; PRB sequence without separate concept round unless required; distribution approval.", "assumptions": "Neon builds HTML to approved template patterns; assumes fixed number of test-send rounds with IT/Veeva staging.", "exclusions": "FDM submission outside agency scope unless separately scoped; extra review rounds change-order.", "appendix": "UTM naming; Veeva fields for campaign/indication/sub-source."}}, {"id": "unbranded_page_net_new", "label": "Unbranded HCP social page (net new)", "tactic_keys": ["organic_social"], "field_defaults": {"marketing_objectives": "Enable paid social activation via compliant brand/unbranded presence; support retargeting journeys.", "tactic_objectives": "Create net-new professional-audience page to house ads; minimal or no organic publishing.", "deliverables": "Facebook (Meta) page setup: naming, handle, profile image, cover, About copy; pharma template; engagement disabled per policy.", "specs_reference": "Profile photo high-res square (~1200×1200 min); cover ~820×312 (note mobile crop); static imagery; HCP-only statement on cover.", "mandatories": "Unbranded look consistent with unbranded campaign; logos/sign-off per legal; disable comments/messenger/posts as approved.", "reviews": "Internal creative review; client L&F + mockup; PRB with screenshots; final approval; Meta engagement-disable via support request (lead time).", "tech_dev_deployment": "Social team builds dev page from setup sheet; creative refreshes screenshots before submission.", "appendix": "UTM conventions for subsequent paid posts; reference social placement guidelines deck if available."}}]}$brief_presets_json$::jsonb,
  'seed v1 from repo config'
)
ON CONFLICT (version) DO NOTHING;

UPDATE brief_template_draft SET
  skeleton = (SELECT skeleton FROM brief_template_bundle WHERE version = 1 LIMIT 1),
  tactic_overrides = (SELECT tactic_overrides FROM brief_template_bundle WHERE version = 1 LIMIT 1),
  presets = (SELECT presets FROM brief_template_bundle WHERE version = 1 LIMIT 1),
  updated_at = now()
WHERE EXISTS (SELECT 1 FROM brief_template_bundle WHERE version = 1);

INSERT INTO brief_template_active (id, published_bundle_id, updated_at)
SELECT 1, b.id, now()
FROM brief_template_bundle b
WHERE b.version = 1
ON CONFLICT (id) DO UPDATE SET
  published_bundle_id = COALESCE(brief_template_active.published_bundle_id, EXCLUDED.published_bundle_id),
  updated_at = CASE
    WHEN brief_template_active.published_bundle_id IS NULL THEN EXCLUDED.updated_at
    ELSE brief_template_active.updated_at
  END;

COMMIT;
